def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A horizontal 5-line copies the color sequence attached at either end
    # across the length of the line.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 5:
                c += 1
            b = c - 1
            for end in (a, b):
                for dr in (-1, 1):
                    seq = []
                    rr = r + dr
                    while 0 <= rr < h and grid[rr][end] not in (0, 5):
                        seq.append(grid[rr][end])
                        rr += dr
                    if seq:
                        for i, color in enumerate(seq):
                            rr = r + dr * (i + 1)
                            if 0 <= rr < h:
                                for cc in range(a, b + 1):
                                    out[rr][cc] = color
                        break

    # A vertical 5-line repeats the adjacent horizontal color pattern
    # along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and grid[r][c] == 5:
                r += 1
            b = r - 1

            for side in (-1, 1):
                nc = c + side
                if not (0 <= nc < w):
                    continue
                rows = [rr for rr in range(h) if grid[rr][nc] not in (0, 5)]
                # Find a contiguous attached block of pattern rows.
                blocks = []
                for rr in rows:
                    if not blocks or rr > blocks[-1][-1] + 1:
                        blocks.append([rr])
                    else:
                        blocks[-1].append(rr)
                block = next((blk for blk in blocks if any(a <= rr <= b for rr in blk)), None)
                if not block:
                    continue

                p0, p1 = block[0], block[-1]
                pattern = []
                for rr in range(p0, p1 + 1):
                    vals = []
                    cc = nc
                    while 0 <= cc < w and grid[rr][cc] not in (0, 5):
                        vals.append(grid[rr][cc])
                        cc += side
                    pattern.append(vals)
                if not pattern or not any(pattern):
                    continue

                width = max(map(len, pattern))
                for rr in range(a, b + 1):
                    vals = pattern[(rr - a) % len(pattern)]
                    for j, color in enumerate(vals):
                        cc = nc + side * j
                        if 0 <= cc < w:
                            out[rr][cc] = color
                break

    return out
